 77	    public BigDecimal calculateProductsSubtotal(CheckoutRequestDto request) {
 78	        BigDecimal subtotal = BigDecimal.ZERO;
 79	        for (var item : request.getItems()) {
 80	            Product product = productService.getProduct(item.getSku());
 81	            BigDecimal itemTotal = product.getPrice().multiply(new BigDecimal(item.getQuantity()));
 82	            subtotal = subtotal.add(itemTotal);
 83	        }
 84	        return subtotal;
 85	    }
