308	    public static class ShippingQuote {
309	        public BigDecimal cost;
310	        public Integer days;
311	
312	        public ShippingQuote(BigDecimal cost, Integer days) {
313	            this.cost = cost;
314	            this.days = days;
315	        }
316	    }
317	}
