251	    private BigDecimal calculateCreditCardInterest(BigDecimal total, Integer installments) {
252	        BigDecimal monthlyRate = new BigDecimal("0.0199");
253	        BigDecimal installmentAmount = total
254	                .multiply(monthlyRate)
255	                .divide(
256	                        BigDecimal.ONE.subtract(
257	                                BigDecimal.ONE.add(monthlyRate).pow(-installments)
258	                        ),
259	                        10,
260	                        RoundingMode.HALF_EVEN
261	                );
262	
263	        BigDecimal totalWithInterest = installmentAmount.multiply(new BigDecimal(installments));
264	        return totalWithInterest.subtract(total);
265	    }
